class HisDatRetencionPersona extends BaseHisDatRetencionPersona {

	/**
     * Obtener un listado de los datos de las retenciones de una persona.
     * 
	 * @param int $idpersona    Identificador de la persona.
	 * @param int $identidad    Identificador de la entidad.
     * @param int $inicio       Inicio de la busqueda.
     * @param int $limite       Limite maximo de la busqueda.
     * @return array    Listado de los datos de las retenciones de una persona.
     */
    public static function obtenerListadoHistoricoRetencionesByIdpersonaEntidad($idpersona, $identidad, $inicio = 0, $limite = 10) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
                ->select('rp.*, 
                    tr.denominacion as tiporetencion, tr.saldolimite as saldolimite')
                ->from('HisDatRetencionPersona rp')
                ->leftjoin('rp.NomTipoRetencion tr')
				->where('rp.idpersona = ? and rp.identidad = ?', array($idpersona, $identidad))
				->orderBy('rp.fechafin, rp.prioridad')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }
	
	/*
     * Obtener la retenci�n de una persona dado el identificador.
     * 
     * @param $idretencperson        	Identificador de la retenci�n.
     * @return DatRetencionPersona    	Objeto de la retenci�n de la persona (clase del dominio).
     */
    public static function obtenerObjRetencionPersonaDadoId($idretencperson) {
        return Doctrine::getTable('HisDatRetencionPersona')->find($idretencperson);
    }

    public function obtenerListadohistoricoOperacionesRetenciones($idhisdatretencionpersona, $limit, $start){

        $sql = "select h.* , dn.numeronomina
		from mod_nomina.his_operacionretencionpersona h
		left join mod_nomina.dat_nomina dn on (dn.idnomina = h.idnomina)
		where h.idhisdatretencionpersona = ? order by h.fechaoperacion DESC";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();

        return $conn->fetchAll($sql, array($idhisdatretencionpersona));
    }

    public function obtenerDatosPersonaRetencionBaja($identidad, $texto, $inicio = 0, $limite = 5)
    {
        $arrayfinal = array();
        $cont = 0; 
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sqlconcat = (!empty($texto)) ? " and (ddi.numero ilike '%$texto%' or dp.nombre ilike '%$texto%' or dp.snombre ilike '%$texto%' or dp.papel ilike '%$texto%' or dp.sapel ilike '%$texto%')" : "";
        $sqlDatosPersona = "select DISTINCT hpb.idpersona, dco.idpersona as personacargoocp, ddi.numero, dp.nombre, 
                    (CASE WHEN (dp.snombre is null) then '' else dp.snombre end ) as snombre, dp.papel, dp.sapel,
                    cpn.idplantillanominal,nc.denominacion as denomcargo, dco.idcargo,
                    (CASE WHEN cpn.denominacion <> '' THEN cpn.orden ||'-'|| cpn.denominacion ELSE 'Sin plantilla nominal' END) as area,
                    cpn.orden as orden, nfe.nivel as ordencargo                     
                    from  mod_nomina.his_personabaja hpb                      
                    LEFT JOIN mod_nomina.dat_cargosocupados dco  on (dco.idpersona = hpb.idpersona and dco.identidad = $identidad)
                    INNER join  mod_nomina.his_datretencionpersona hdrp on (hpb.idpersona = hdrp.idpersona and hdrp.identidad = $identidad)             
                    INNER JOIN mod_persona.dat_persona dp on (hpb.idpersona = dp.idpersona) 
                    INNER JOIN mod_persona.dat_docidentidad ddi on (ddi.idpersona = dp.idpersona and ddi.principal = 1)            
                    LEFT JOIN mod_nomina.conf_plantillanominalcargo cpnc on (cpnc.idcargo = dco.idcargo)
                    LEFT JOIN mod_nomina.conf_plantillanominal cpn on (cpn.idplantillanominal = cpnc.idplantillanominal)            
                    LEFT JOIN mod_estructuracomp.dat_cargo dc on (dc.idcargo = dco.idcargo)
                    LEFT JOIN mod_estructuracomp.nom_cargo nc on (nc.idnomcargo = dc.idnomcargo) 
                    LEFT JOIN mod_estructuracomp.nom_filaestruc nfe on (nfe.idfila = dc.idcargo)
                    where hdrp.identidad = $identidad and dco.idpersona is null 
                    and hpb.idpersona not in (select cpr.idpersona from mod_nomina.conf_personaretencion cpr) ORDER BY cpn.orden ASC, nfe.nivel ASC";
        $resultado = $conn->fetchAll($sqlDatosPersona);
        $arrretpersonas = HisDatRetencionPersona::obtenerHistoricoRetencionesEntidad($identidad);
        $arrretpersonas = $this->indexarArreglo($arrretpersonas, "idpersona");
        $arrcdgoscontables = ConfigPersonaCodigoContable::obtenerConfigDadoIdEntidad($identidad);
        $arrcdgoscontables = $this->indexarArreglo($arrcdgoscontables, "idpersona");
        foreach ($resultado as $i => $value){
            $arrayfinal[$cont]['idpersona'] = $value['idpersona'];
            $arrayfinal[$cont]['personacargoocp'] = $value['personacargoocp'];
            $arrayfinal[$cont]['identidad'] = $value['identidad'];
            $arrayfinal[$cont]['numero'] = $value['numero'];
            $arrayfinal[$cont]['nombre'] = $value['nombre'];
            $arrayfinal[$cont]['snombre'] = $value['snombre'];
            $arrayfinal[$cont]['papel'] = $value['papel'];
            $arrayfinal[$cont]['sapel'] = $value['sapel'];
            $arrayfinal[$cont]['idplantillanominal'] = $value['idplantillanominal'];
            $arrayfinal[$cont]['denomcargo'] = $value['denomcargo'];
            $arrayfinal[$cont]['idcargo'] = $value['idcargo']; 
            $arrayfinal[$cont]['area'] = $value['area'];
            $arrayfinal[$cont]['orden'] = $value['orden'];
            $arrayfinal[$cont]['plantillanominal'] = $value['orden'].'-'.$value['area'];
            $arrayfinal[$cont]['ordencargo'] = $value['ordencargo'];
            $arrayfinal[$cont]['cargo'] = ($value['idcargo'] != null) ? $value['denomcargo'] : '';
            $arrayfinal[$cont]['cdgocontable'] = ($arrcdgoscontables[$value['idpersona']]['cdgocontable'])?$arrcdgoscontables[$value['idpersona']]['cdgocontable']:'';
            $cont++;
        }
        return $arrayfinal;
    }

    public static function cantPersonaRetencionBaja($identidad) {
        $sql = "select distinct dp.idpersona from  mod_nomina.his_datretencionpersona hdrp
        left join mod_nomina.dat_cargosocupados dco on (dco.idpersona = hdrp.idpersona and dco.identidad = ?)
        LEFT JOIN mod_nomina.conf_plantillanominalcargo cpnc on (cpnc.idcargo = dco.idcargo)
        inner join mod_persona.dat_persona dp on (hdrp.idpersona = dp.idpersona)
        where hdrp.identidad = ? and dco.idpersona is null";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $resultado = $conn->fetchAll($sql,array($identidad,$identidad));
        return count($resultado);

    }
    
    public static function obtenerHistoricoRetencionesEntidad($identidad) {

        //Devolviendo el listado de las retenciones historicas de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('hdrp.*')
            ->from('HisDatRetencionPersona hdrp')
            ->where('hdrp.identidad = ?', array($identidad))
            ->fetchArray();
    }

    public function indexarArreglo($array, $indice)
    {
        $arrayfinal = array();
        foreach ($array as $valor) {
            $arrayfinal[$valor[$indice]] = $valor;
        }
        return $arrayfinal;
    }

}
